+/** Real HTTP client negotiation for existing suites. No mocked responses or catch-all success. */
+export async function creationFetch(input, init) {
+    const response = await globalThis.fetch(input, init);
+    if (response.status !== 428) return response;
+    const challenge = await response.clone().json();
+    const mutation = challenge.error === 'MUTATION_PROOF_REQUIRED';
+    const proof = mutation ? challenge.mutationProof : challenge.creationProof;
+    if ((!mutation && challenge.error !== 'CREATION_PROOF_REQUIRED') || typeof proof !== 'string') return response;
+    const header = mutation ? 'X-Tobu-Mutation' : 'X-Tobu-Creation';
+    const headers = new globalThis.Headers(init?.headers);
+    if (headers.has(header)) return response; // Never loop on a rejected supplied proof.
+    headers.set(header, proof);
+    return globalThis.fetch(input, { ...init, headers });
+}"},{"sha":"5d82110ea6b6f0ac002aee50478dca59958c9ded","filename":"apps/api/tests/fixtures/domain-revisions-migration-child.mjs","status":"added","additions":18,"deletions":0,"changes":18,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Ftests%2Ffixtures%2Fdomain-revisions-migration-child.mjs","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Ftests%2Ffixtures%2Fdomain-revisions-migration-child.mjs","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fapi%2Ftests%2Ffixtures%2Fdomain-revisions-migration-child.mjs?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,18 @@
