+    const target = await migrationTarget(client, db, 'test', 'database-id');
+    assert.equal(target.deployment.id, id.toHexString());
+    const rotated = new MongoClient('mongodb://different:rotated@localhost/db?replicaSet=rs');
+    assert.equal(migrationTargetHash(target), migrationTargetHash(await migrationTarget(rotated, db, 'test', 'database-id')));
+    assert.notEqual(migrationTargetHash(target), migrationTargetHash({ ...target, databaseId: 'clone' }));
+    assert.notEqual(migrationTargetHash(target), migrationTargetHash({ ...target, deployment: { ...target.deployment, id: new ObjectId().toHexString() } }));
+    const denied = {
+        databaseName: 'db',
+        admin: () => ({
+            command: async (command) => {
+                if (command.hello) return { setName: 'rs' };
+                throw new Error('denied');
+            }
+        })
+    };
+    await assert.rejects(migrationTarget(client, denied, 'test'), /denied/);
+    for (const version of [undefined, 1, '2']) assert.throws(() => requireCurrentIdentity(version), /Legacy migration identity/);
+    requireCurrentIdentity(2);
+});"},{"sha":"ef0374a6cd870b0bd32090e4bd68d26cd625c034","filename":"apps/web/src/app/accounts/account-overview/account-overview.html","status":"modified","additions":148,"deletions":39,"changes":187,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Faccount-overview%2Faccount-overview.html","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Faccount-overview%2Faccount-overview.html","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Faccount-overview%2Faccount-overview.html?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -8,41 +8,60 @@ <h1 class="text-3xl font-bold text-primary-900 dark:text-primary-100">
