+<section class="activity card" aria-labelledby="activity-heading">
+  <header>
+    <div>
+      <h1 id="activity-heading">Kontoaktivitäten</h1>
+      <p>Wer hat was geändert? Gespeicherte Ereignisse dieses Kontos.</p>
+    </div>
+    <a [routerLink]="['/accounts', accountId()]">Zur Kontoübersicht</a>
+  </header>
+  <form
+    class="filters"
+    (ngSubmit)="applyFilters()"
+    aria-label="Aktivitäten filtern"
+  >
+    <label
+      >Ereignisart<select name="code" [(ngModel)]="form.code">
+        <option value="">Alle Ereignisarten</option>
+        @for (code of codes; track code) {
+          <option [value]="code">{{ codeNames[code] }}</option>
+        }
+        <option value="legacy.unknown">Unbekannte Ereignisart</option>
+      </select></label
+    >
+    <label
+      >Akteur<select name="actorKind" [(ngModel)]="form.actorKind">
+        <option value="">Alle Akteure</option>
+        <option value="user">Benutzer</option>
+        <option value="system">System</option>
+        <option value="unknown">Unbekannt (Altbestand)</option>
+      </select></label
+    >
+    <label
+      >Objektart<select name="subjectKind" [(ngModel)]="form.subjectKind">
+        <option value="">Alle Objektarten</option>
+        @for (kind of kinds; track kind) {
+          <option [value]="kind">{{ kindLabels[kind] }}</option>
+        }
+      </select></label
+    >
+    <label
+      >Objekt-ID<input
+        name="subjectId"
+        [(ngModel)]="form.subjectId"
+        maxlength="24"
+        pattern="[a-fA-F0-9]{24}"
+        autocomplete="off"
+        aria-describedby="subject-help"
+    /></label>
+    <label
+      >Von (einschließlich)<input
+        type="datetime-local"
+        step="0.001"
+        name="from"
+        [(ngModel)]="form.from"
+    /></label>
+    <label
+      >Bis (ausschließlich)<input
+        type="datetime-local"
+        step="0.001"
+        name="to"
+        [(ngModel)]="form.to"
+    /></label>
+    <label
+      >Ereignisse pro Seite<select name="limit" [(ngModel)]="form.limit">
+        <option value="20">20</option>
+        <option value="50">50</option>
+        <option value="100">100</option>
+      </select></label
+    >
+    <div class="filter-actions">
+      <button type="submit" [disabled]="loading()">Filter anwenden</button
+      ><button type="button" (click)="resetFilters()">Zurücksetzen</button>
+    </div>
+  </form>
+  <p id="subject-help" class="muted">
+    Objektfilter verwenden nur Referenzen dieses Kontos. Zeitangaben in
+    {{ zone }}.
+  </p>
+  <p
+    #resultsStatus
+    class="result-status"
+    role="status"
+    aria-live="polite"
+    tabindex="-1"
+  >
+    {{
+      loading()
+        ? "Aktivitäten werden geladen …"
+        : items().length + " Ereignisse geladen"
+    }}{{ !loading() && nextCursor() ? " – weitere Seiten verfügbar" : "" }}
+  </p>
+  @if (error()) {
+    <div role="alert" class="error">
+      <p>{{ error() }}</p>
+      <button type="button" (click)="retry()" [disabled]="loading()">
+        Erneut versuchen
+      </button>
+    </div>
+  }
+  @if (!loading() && !error() && items().length === 0) {
+    <p>
+      {{
+        nextCursor()
+          ? "In diesem Abschnitt keine passenden Aktivitäten. Weitere Seiten können Treffer enthalten."
+          : "Keine passenden Aktivitäten vorhanden."
+      }}
+    </p>
+  }
+  <ol
+    class="activity-list"
+    aria-label="Geladene Kontoaktivitäten"
+    [attr.aria-busy]="loading()"
+  >
+    @for (group of groups(); track group.key) {
+      <li class="activity-group">
+        @if (group.grouped) {
+          <details>
+            <summary>
+              {{ group.events.length }} geladene Ereignisse einer Aktion
+            </summary>
+            <p class="group-notice">
+              Gezählt werden nur geladene Ereignisse. Weitere, übersprungene
+              oder fehlgeschlagene Teile der Aktion sind daraus nicht
+              bestimmbar. Dies ist keine Gesamterfolgsmeldung.
+            </p>
+            <ol>
+              @for (event of group.events; track event.id) {
+                <li [attr.data-event-id]="event.id">
+                  <ng-container
+                    [ngTemplateOutlet]="entry"
+                    [ngTemplateOutletContext]="{ $implicit: event }"
+                  />
+                </li>
+              }
+            </ol>
+          </details>
+        } @else {
+          <div [attr.data-event-id]="group.events[0]!.id">
+            <ng-container
+              [ngTemplateOutlet]="entry"
+              [ngTemplateOutletContext]="{ $implicit: group.events[0] }"
+            />
+          </div>
+        }
+      </li>
+    }
+  </ol>
+  <ng-template #entry let-event>
+    <div class="entry-heading">
+      <strong>{{ eventText(event) }}</strong
+      ><time [attr.datetime]="event.occurredAt">{{
+        dateText(event.occurredAt)
+      }}</time>
+    </div>
+    <p class="actor">
+      {{ actorText(event.actor) }} · {{ triggerText(event) }}
+      @if (event.trigger.initiatedBy?.displayName) {
+        <span>
+          · angestoßen von {{ event.trigger.initiatedBy.displayName }}</span
+        >
+      }
+    </p>
+    @if (event.subject) {
+      @if (event.subject.deleted) {
+        <span class="muted"
+          >{{ event.subject.label || kindLabels[event.subject.kind] }} (gelöscht
+          oder nicht mehr verfügbar)</span
+        >
+      } @else {
+        <a
+          [routerLink]="['/accounts', accountId(), 'activity']"
+          [queryParams]="{
+            subjectKind: event.subject.kind,
+            subjectId: event.subject.id,
+          }"
+          >Weitere Aktivitäten:
+          {{ event.subject.label || kindLabels[event.subject.kind] }}</a
+        >
+      }
+    } @else if (event.detailsUnavailable) {
+      <span class="muted">Objektdetails nicht verfügbar</span>
+    }
+  </ng-template>
+  <button
+    class="load-more"
+    type="button"
+    (click)="loadMore()"
+    [disabled]="loading() || !nextCursor()"
+  >
+    {{
+      loading()
+        ? "Wird geladen …"
+        : nextCursor()
+          ? "Weitere Aktivitäten laden"
+          : "Keine weitere Seite verfügbar"
+    }}
+  </button>
+</section>"},{"sha":"a28405c904ebc8d69402e379b0196650acd5362c","filename":"apps/web/src/app/accounts/activity/account-activity.scss","status":"added","additions":157,"deletions":0,"changes":157,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.scss","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.scss","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.scss?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,157 @@
+:host {
+  display: block;
+  min-width: 0;
+}
+.activity {
+  padding: 1.25rem;
+  overflow-wrap: anywhere;
+}
+header,
+.entry-heading {
+  display: flex;
+  justify-content: space-between;
+  gap: 1rem;
+  align-items: baseline;
+}
+h1 {
+  font-size: 1.5rem;
+  font-weight: 650;
+  margin: 0 0 0.5rem;
+}
+.filters {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 1rem;
+  margin: 1.25rem 0 0.75rem;
+}
+label {
+  display: flex;
+  flex-direction: column;
+  gap: 0.4rem;
+  font-weight: 600;
+}
+input,
+select {
+  width: 100%;
+  min-width: 0;
+  padding: 0.65rem;
+  border: 1px solid var(--p-form-field-border-color);
+  border-radius: 0.35rem;
+  background: var(--p-form-field-background);
+  color: var(--p-form-field-color);
+  font: inherit;
+}
+input:hover,
+select:hover {
+  border-color: var(--p-form-field-hover-border-color);
+}
+input:focus,
+select:focus {
+  border-color: var(--p-form-field-focus-border-color);
+}
+input:disabled,
+select:disabled {
+  background: var(--p-form-field-disabled-background);
+  color: var(--p-form-field-disabled-color);
+}
+button {
+  padding: 0.6rem 0.9rem;
+  border: 1px solid var(--p-primary-color);
+  background: var(--p-primary-color);
+  color: var(--p-primary-contrast-color);
+  border-radius: 0.35rem;
+  font: inherit;
+  cursor: pointer;
+}
+button:enabled:hover {
+  border-color: var(--p-primary-hover-color);
+  background: var(--p-primary-hover-color);
+}
+button:enabled:active {
+  border-color: var(--p-primary-active-color);
+  background: var(--p-primary-active-color);
+}
+button:disabled {
+  opacity: var(--p-disabled-opacity);
+  cursor: default;
+}
+a {
+  text-decoration: underline;
+  color: var(--p-primary-color);
+}
+:is(button, a, input, select, summary):focus-visible {
+  outline: 3px solid var(--p-focus-ring-color);
+  outline-offset: 3px;
+}
+.filter-actions {
+  display: flex;
+  align-items: end;
+  gap: 0.6rem;
+  flex-wrap: wrap;
+}
+.activity-list {
+  list-style: none;
+  padding: 0;
+}
+.activity-group {
+  border-top: 1px solid var(--p-content-border-color);
+  padding: 1rem 0;
+}
+.activity-group ol {
+  padding-left: 1.5rem;
+}
+.activity-group li + li {
+  margin-top: 1rem;
+}
+summary {
+  cursor: pointer;
+  font-weight: 600;
+  padding: 0.35rem 0;
+}
+.actor,
+.muted,
+time {
+  color: var(--p-text-muted-color);
+}
+time {
+  font-size: 0.9rem;
+  white-space: nowrap;
+}
+.group-notice {
+  border-left: 3px solid var(--p-primary-color);
+  padding: 0.6rem;
+}
+.error {
+  border: 1px solid var(--p-form-field-invalid-border-color);
+  padding: 0.8rem;
+  margin: 0.8rem 0;
+}
+.result-status {
+  margin: 1rem 0;
+}
+.result-status:focus {
+  outline: 2px solid var(--p-focus-ring-color);
+  outline-offset: 3px;
+}
+.load-more {
+  margin-top: 0.8rem;
+}
+@media (max-width: 700px) {
+  .activity {
+    padding: 1rem;
+  }
+  header,
+  .entry-heading {
+    flex-direction: column;
+    gap: 0.45rem;
+  }
+  .filters {
+    grid-template-columns: minmax(0, 1fr);
+  }
+  time {
+    white-space: normal;
+  }
+  .load-more {
+    width: 100%;
+  }
+}"},{"sha":"fa25312614f74d58e52c2faae91d2b0d116f68ac","filename":"apps/web/src/app/accounts/activity/account-activity.ts","status":"added","additions":223,"deletions":0,"changes":223,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Faccount-activity.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,223 @@
+import {
+  ChangeDetectionStrategy,
+  Component,
+  computed,
+  DestroyRef,
+  ElementRef,
+  inject,
+  signal,
+  ViewChild,
+} from "@angular/core";
+import { ActivatedRoute, Router, RouterLink } from "@angular/router";
+import { FormsModule } from "@angular/forms";
+import { NgTemplateOutlet } from "@angular/common";
+import { takeUntilDestroyed } from "@angular/core/rxjs-interop";
+import { combineLatest, Subscription } from "rxjs";
+import { DateTime } from "luxon";
+import {
+  ACTIVITY_CODES,
+  ActivitySubjectKinds,
+  ActivityQuerySchema,
+  activityCodeNames,
+  ACTIVITY_TRIGGER_LABELS_DE,
+  renderActivityActor,
+  renderActivityText,
+  type ActivityItem,
+} from "@tobu/contracts/activity";
+import { ActivityDataService } from "./activity-data.service";
+import {
+  activityDisplayZone,
+  formatActivityInstant,
+  groupLoadedActivity,
+} from "./activity-presentation";
+
+@Component({
+  selector: "tbf-account-activity",
+  standalone: true,
+  changeDetection: ChangeDetectionStrategy.OnPush,
+  imports: [FormsModule, RouterLink, NgTemplateOutlet],
+  templateUrl: "./account-activity.html",
+  styleUrl: "./account-activity.scss",
+})
+export class AccountActivity {
+  private readonly route = inject(ActivatedRoute);
+  private readonly router = inject(Router);
+  private readonly data = inject(ActivityDataService);
+  private readonly destroy = inject(DestroyRef);
+  private request?: Subscription;
+  private generation = 0;
+  private filters: Record<string, string> = {};
+  private validFilters = false;
+  @ViewChild("resultsStatus") private status?: ElementRef<HTMLElement>;
+  protected readonly accountId = signal("");
+  protected readonly items = signal<ActivityItem[]>([]);
+  protected readonly groups = computed(() => groupLoadedActivity(this.items()));
+  protected readonly loading = signal(false);
+  protected readonly error = signal("");
+  protected readonly nextCursor = signal<string | null>(null);
+  protected readonly codes = ACTIVITY_CODES;
+  protected readonly kinds = ActivitySubjectKinds;
+  protected readonly codeNames = activityCodeNames;
+  protected readonly zone = activityDisplayZone();
+  protected form = {
+    code: "",
+    actorKind: "",
+    subjectKind: "",
+    subjectId: "",
+    from: "",
+    to: "",
+    limit: "20",
+  };
+  protected readonly kindLabels: Record<string, string> = {
+    account: "Konto",
+    member: "Mitglied",
+    transaction: "Buchung",
+    category: "Kategorie",
+    memberIncome: "Einkommen",
+    contributionRule: "Beitragsregel",
+    categoryBudget: "Budget",
+    carryOver: "Übertrag",
+    accountBalance: "Kontostand",
+    legacyRecurrence: "Wiederkehrende Buchung",
+    recurrence: "Buchungsvorlage",
+    occurrence: "Vorlagenvorkommen",
+  };
+  protected readonly actorText = renderActivityActor;
+  protected readonly eventText = renderActivityText;
+  protected readonly dateText = (date: string) =>
+    formatActivityInstant(date, this.zone);
+  protected readonly triggerText = (item: ActivityItem) =>
+    ACTIVITY_TRIGGER_LABELS_DE[item.trigger.kind];
+
+  constructor() {
+    combineLatest([this.route.parent!.paramMap, this.route.queryParamMap])
+      .pipe(takeUntilDestroyed())
+      .subscribe(([path, query]) => {
+        this.generation++;
+        this.validFilters = false;
+        this.filters = {};
+        this.request?.unsubscribe();
+        this.accountId.set(path.get("accountId") ?? "");
+        this.items.set([]);
+        this.nextCursor.set(null);
+        this.error.set("");
+        this.loading.set(false);
+        const raw: Record<string, string> = {};
+        for (const key of query.keys)
+          if (query.get(key)) raw[key] = query.get(key)!;
+        const parsed = ActivityQuerySchema.safeParse(raw);
+        if (!parsed.success || raw["cursor"]) {
+          this.error.set(
+            "Die Aktivitätsfilter sind ungültig. Bitte zurücksetzen.",
+          );
+          return;
+        }
+        this.filters = raw;
+        this.validFilters = true;
+        this.form = {
+          code: raw["code"] ?? "",
+          actorKind: raw["actorKind"] ?? "",
+          subjectKind: raw["subjectKind"] ?? "",
+          subjectId: raw["subjectId"] ?? "",
+          from: this.localInput(raw["from"]),
+          to: this.localInput(raw["to"]),
+          limit: raw["limit"] ?? "20",
+        };
+        this.load(false);
+      });
+    this.destroy.onDestroy(() => this.request?.unsubscribe());
+  }
+  private localInput(value?: string) {
+    return value
+      ? DateTime.fromISO(value, { zone: "utc" })
+          .setZone(this.zone)
+          .toFormat("yyyy-LL-dd'T'HH:mm:ss.SSS")
+      : "";
+  }
+  protected applyFilters() {
+    const query: Record<string, string> = {};
+    for (const [key, value] of Object.entries(this.form))
+      if (value.trim()) {
+        if (key === "from" || key === "to") {
+          const date = DateTime.fromISO(value, { zone: this.zone });
+          if (!date.isValid) {
+            this.error.set("Bitte einen gültigen Zeitpunkt eingeben.");
+            return;
+          }
+          query[key] = date.toUTC().toISO()!;
+        } else query[key] = value.trim();
+      }
+    if (!ActivityQuerySchema.safeParse(query).success) {
+      this.error.set(
+        "Bitte gültige Filter und einen Zeitraum mit Von vor Bis eingeben.",
+      );
+      return;
+    }
+    void this.router.navigate([], {
+      relativeTo: this.route,
+      queryParams: query,
+    });
+  }
+  protected resetFilters() {
+    void this.router.navigate([], { relativeTo: this.route, queryParams: {} });
+  }
+  protected loadMore() {
+    if (this.nextCursor() && !this.loading()) this.load(true);
+  }
+  protected retry() {
+    if (!this.loading())
+      this.load(this.items().length > 0 || this.nextCursor() !== null);
+  }
+  private load(append: boolean) {
+    if (!this.validFilters) return;
+    const generation = this.generation;
+    this.loading.set(true);
+    this.error.set("");
+    this.request = this.data
+      .get(
+        this.accountId(),
+        this.filters,
+        append ? (this.nextCursor() ?? undefined) : undefined,
+      )
+      .pipe(takeUntilDestroyed(this.destroy))
+      .subscribe({
+        next: (page) => {
+          if (generation !== this.generation) return;
+          const seen = new Set(
+            (append ? this.items() : []).map((item) => item.id),
+          );
+          const incoming = page.items.filter((item) => {
+            if (seen.has(item.id)) return false;
+            seen.add(item.id);
+            return true;
+          });
+          this.items.set([...(append ? this.items() : []), ...incoming]);
+          this.nextCursor.set(page.nextCursor);
+          this.loading.set(false);
+          if (append)
+            queueMicrotask(() =>
+              this.status?.nativeElement.focus({ preventScroll: true }),
+            );
+        },
+        error: (error: { status?: number }) => {
+          if (generation !== this.generation) return;
+          this.loading.set(false);
+          if (
+            error.status === 401 ||
+            error.status === 403 ||
+            error.status === 404
+          ) {
+            this.items.set([]);
+            this.nextCursor.set(null);
+          }
+          this.error.set(
+            error.status === 404
+              ? "Diese Kontoaktivitäten sind nicht verfügbar."
+              : error.status === 422
+                ? "Der Seitenbeleg oder die Filter sind nicht mehr gültig. Bitte zurücksetzen."
+                : "Aktivitäten konnten nicht geladen werden. Bitte erneut versuchen.",
+          );
+        },
+      });
+  }
+}"},{"sha":"101a591d7bfd42f0a50f517fcb996eb73b65963d","filename":"apps/web/src/app/accounts/activity/activity-data.service.ts","status":"added","additions":21,"deletions":0,"changes":21,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,21 @@
+import { inject, Injectable } from "@angular/core";
