+import { DateTime } from "luxon";
+import type { ActivityItem } from "@tobu/contracts/activity";
+
+export interface ActivityGroup {
+  key: string;
+  events: ActivityItem[];
+  grouped: boolean;
+}
+/** Rebuild from all loaded pages, never invent an expected count or a successful batch result. */
+export function groupLoadedActivity(
+  items: readonly ActivityItem[],
+): ActivityGroup[] {
+  const seen = new Set<string>();
+  const groups = new Map<string, ActivityGroup>();
+  for (const item of items) {
+    if (seen.has(item.id)) continue;
+    seen.add(item.id);
+    const key = item.group ? "group:" + item.group.key : "event:" + item.id;
+    const group = groups.get(key) ?? {
+      key,
+      events: [],
+      grouped: item.group?.source === "batch",
+    };
+    group.events.push(item);
+    group.grouped ||= group.events.length > 1;
+    groups.set(key, group);
+  }
+  return [...groups.values()];
+}
+export const activityDisplayZone = () =>
+  Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
+export function formatActivityInstant(
+  instant: string,
+  zone = activityDisplayZone(),
+) {
+  const value = DateTime.fromISO(instant, { zone: "utc" }).setZone(zone);
+  return value.isValid
+    ? value.setLocale("de").toFormat("dd.LL.yyyy HH:mm:ss ZZZZ")
+    : "Zeitpunkt nicht verfügbar";
+}"},{"sha":"86d75ad8783485cc65684f904d71d435171272d6","filename":"apps/web/src/app/accounts/month-view/components/einzahlung-drawer.ts","status":"modified","additions":1,"deletions":0,"changes":1,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Fmonth-view%2Fcomponents%2Feinzahlung-drawer.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Fmonth-view%2Fcomponents%2Feinzahlung-drawer.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Fmonth-view%2Fcomponents%2Feinzahlung-drawer.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -57,6 +57,7 @@ interface EinzahlungFormModel {
