+        name: "Filter anwenden",
+        exact: true,
+      });
+      await apply.focus();
+      await page.keyboard.press("Enter");
+      await expect(status).toContainText("0 Ereignisse geladen");
+      assertStatus(
+        await capture("empty-filter"),
+        "0 Ereignisse geladen",
