+      );
+      await page
+        .getByRole("button", { name: "Zurücksetzen", exact: true })
+        .click();
+      await expect(status).toContainText("20 Ereignisse geladen");
+      // Actual membership revocation produces a real 404 while the page remains open.
+      await db
+        .collection("accounts")
