+    expect(requests.at(-1)?.searchParams.get("actorKind")).toBe("system");
+    expect(
+      await page
+        .locator(".activity")
+        .evaluate((node) => node.scrollWidth <= node.clientWidth),
+    ).toBe(true);
+  });
