+        const duplicate = error instanceof Error && 'code' in error && error.code === 11000;
+        if (!unknown && !duplicate) throw error;
+        await checkAuthority(context);
+        const prior = await readback(events, ids);
+        if (prior) return prior;
+        if (unknown) throw new ActivityCommitUnknown('ACTIVITY_COMMIT_UNKNOWN_READBACK_REQUIRED', { cause: error });
+        throw error;
+    }
+}"},{"sha":"bd208dec59f1921e5eb88e825aea6597e616a190","filename":"apps/api/src/services/creation-proof.ts","status":"added","additions":78,"deletions":0,"changes":78,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Fcreation-proof.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Fcreation-proof.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fapi%2Fsrc%2Fservices%2Fcreation-proof.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,78 @@
+import { createHash, sign, verify } from 'node:crypto';
+import type { Request, Response } from 'express';
+import { Types } from 'mongoose';
+import { keys } from '../auth/config.js';
+
+// This is a signed domain id, NOT an access token or a client-selected event command.
+// The two-part format and purpose prefix cannot be used as an authentication JWT.
+const purpose = 'tobu-domain-creation-v1:';
+const generations = new WeakMap<Types.ObjectId, number>();
+export const creationGeneration = (id: Types.ObjectId) => generations.get(id);
+export function canonical(value: unknown): string {
+    if (value instanceof Date) return JSON.stringify(value.toISOString());
+    if (value instanceof Types.ObjectId) return JSON.stringify(String(value));
+    if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
+    if (value && typeof value === 'object')
+        return (
+            '{' +
+            Object.entries(value)
+                .filter(([, v]) => v !== undefined)
+                .sort(([a], [b]) => a.localeCompare(b))
+                .map(([k, v]) => JSON.stringify(k) + ':' + canonical(v))
+                .join(',') +
+            '}'
+        );
+    return JSON.stringify(value);
+}
+export const fingerprint = (value: unknown) => createHash('sha256').update(canonical(value)).digest('hex');
+
+/** Bind the first authorized domain revision to a retry. A later revision fails closed, never reapplies an old change. */
+export function mutationPermit(req: Request, identity: string): { status: number; body: Record<string, unknown> } | null {
+    const binding = { user: req.user!.sub, resource: req.method + ':' + req.originalUrl, payload: fingerprint(req.body ?? null), identity };
+    const prefix = 'tobu-domain-mutation-v1:';
+    const token = req.get('X-Tobu-Mutation');
+    if (!token) {
+        const data = Buffer.from(JSON.stringify(binding)).toString('base64url');
+        const signature = sign('sha256', Buffer.from(prefix + data), keys.access.privateKey).toString('base64url');
+        return { status: 428, body: { error: 'MUTATION_PROOF_REQUIRED', mutationProof: data + '.' + signature } };
+    }
+    try {
+        if (token.length > 2048) throw new Error();
+        const [data, signature, extra] = token.split('.');
+        if (!data || !signature || extra || !verify('sha256', Buffer.from(prefix + data), keys.access.publicKey, Buffer.from(signature, 'base64url'))) throw new Error();
+        const claim = JSON.parse(Buffer.from(data, 'base64url').toString('utf8'));
+        if (claim.user !== binding.user || claim.resource !== binding.resource || claim.payload !== binding.payload) throw new Error();
+        if (claim.identity !== identity) return { status: 409, body: { error: 'MUTATION_REVISION_STALE' } };
+        return null;
+    } catch {
+        return { status: 422, body: { error: 'INVALID_MUTATION_PROOF' } };
+    }
+}
+
+/** Missing proof negotiates WITHOUT writes. Retain the proof before submitting the actual creation. */
+export function creationId(req: Request, res: Response, resource: string, payload: unknown, generation?: number): Types.ObjectId | null {
+    const binding = { user: req.user!.sub, resource, payload: fingerprint(payload) };
+    const token = req.get('X-Tobu-Creation');
+    if (!token) {
+        const data = Buffer.from(JSON.stringify({ ...binding, id: String(new Types.ObjectId()), ...(generation === undefined ? {} : { generation }) })).toString('base64url');
+        const signature = sign('sha256', Buffer.from(purpose + data), keys.access.privateKey).toString('base64url');
+        res.status(428).json({ error: 'CREATION_PROOF_REQUIRED', creationProof: data + '.' + signature });
+        return null;
+    }
+    try {
+        if (token.length > 2048) throw new Error();
+        const [data, signature, extra] = token.split('.');
+        if (!data || !signature || extra || !verify('sha256', Buffer.from(purpose + data), keys.access.publicKey, Buffer.from(signature, 'base64url'))) throw new Error();
+        const claim = JSON.parse(Buffer.from(data, 'base64url').toString('utf8'));
+        if (claim.user !== binding.user || claim.resource !== resource || claim.payload !== binding.payload || !/^[a-f\d]{24}$/.test(claim.id)) throw new Error();
+        const id = new Types.ObjectId(claim.id);
+        if (generation !== undefined) {
+            if (!Number.isSafeInteger(claim.generation) || claim.generation < 0) throw new Error();
+            generations.set(id, claim.generation);
+        }
+        return id;
+    } catch {
+        res.status(422).json({ error: 'INVALID_CREATION_PROOF' });
+        return null;
+    }
+}"},{"sha":"7307e52a4ed9c75413f0f9d9d253773ff261869d","filename":"apps/api/src/services/recurrence-activity-scope.ts","status":"added","additions":119,"deletions":0,"changes":119,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity-scope.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity-scope.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity-scope.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,119 @@
+import mongoose, { Types, type ClientSession } from 'mongoose';
+import { z } from 'zod';
+import { ObjId } from '@tobu/contracts/common';
+import { MonthKeySchema } from '@tobu/contracts/calendar';
+import type { ActivityWriteEvent } from '@tobu/contracts/activity';
+
+const Id = ObjId.transform((id) => id.toLowerCase());
+const base = { id: Id, accountId: Id };
+const RecordSchema = z.discriminatedUnion('kind', [
+    z.strictObject({ ...base, kind: z.literal('recurrence') }),
+    z.strictObject({ ...base, kind: z.literal('revision'), recurrenceId: Id }),
+    z.strictObject({ ...base, kind: z.literal('occurrence'), recurrenceId: Id, occurrenceKey: MonthKeySchema, transactionId: Id.nullable().default(null) })
+]);
+export type RecurrenceScopeRecord = z.infer<typeof RecordSchema>;
+export type RecurrenceScopeKind = RecurrenceScopeRecord['kind'];
+export interface RecurrenceScopePort {
+    readonly kind: 'recurrence-activity-scope';
+}
+type Proof = { readonly value: RecurrenceScopeRecord };
+type Loader = (request: {
+    readonly session: ClientSession;
+    readonly kind: RecurrenceScopeKind;
+    readonly id: string;
+    readonly accountId: string;
+    /** Attests only this lookup, not another request, phase or transaction. Query using session before calling. */
+    readonly attest: (row: unknown) => Proof;
+}) => Promise<Proof | null>;
+const ports = new WeakMap<object, Loader>();
+export class RecurrenceActivityScopeError extends Error {}
+function fail(code: string): never {
+    throw new RecurrenceActivityScopeError(code);
+}
+
+/** Server-internal port. No registry, collection-name option, HTTP input or production domain implementation. */
+export function createRecurrenceActivityScope(loader: Loader): RecurrenceScopePort {
+    const port = Object.freeze({ kind: 'recurrence-activity-scope' as const });
+    ports.set(port, loader);
+    return port;
+}
+export const isRecurrenceActivityScope = (port: unknown): port is RecurrenceScopePort => !!port && typeof port === 'object' && ports.has(port);
+
+export async function resolveRecurrenceActivityScope(port: RecurrenceScopePort, session: ClientSession, kind: RecurrenceScopeKind, id: string, accountId: string) {
+    if (!isRecurrenceActivityScope(port) || !session.inTransaction()) fail('ACTIVITY_E07_SCOPE_CAPABILITY_REQUIRED');
+    const transaction = session.transaction;
+    const active = () => session.inTransaction() && session.transaction === transaction;
+    const proofs = new WeakSet<object>();
+    const result = await ports.get(port)!({
+        session,
+        kind,
+        id,
+        accountId,
+        attest(row) {
+            if (!active()) return fail('ACTIVITY_E07_SCOPE_SESSION_REQUIRED');
+            const proof = Object.freeze({ value: Object.freeze(RecordSchema.parse(row)) });
+            proofs.add(proof);
+            return proof;
+        }
+    });
+    if (!active()) fail('ACTIVITY_E07_SCOPE_SESSION_REQUIRED');
+    if (result === null) return null;
+    if (!proofs.has(result)) fail('ACTIVITY_E07_SCOPE_WITNESS_INVALID');
+    const row = result.value;
+    if (row.kind !== kind || row.id !== id || row.accountId !== accountId) fail('ACTIVITY_E07_SCOPE_MISMATCH');
+    return row;
+}
+
+/** Validate identity/relations only; future domain guards still own config, finance, sparse-state and delete eligibility. */
+export async function checkRecurrenceActivityScope(port: RecurrenceScopePort, event: ActivityWriteEvent, session: ClientSession, phase: 'before' | 'after') {
+    const p = event.params as Record<string, unknown>;
+    const recurrenceId = String(p.recurrenceId),
+        accountId = event.accountId;
+    const load = (kind: RecurrenceScopeKind, id: string) => resolveRecurrenceActivityScope(port, session, kind, id, accountId);
+    const parent = await load('recurrence', recurrenceId);
+    const absent = (event.code === 'recurrence.created' && phase === 'before') || (event.code === 'recurrence.deleted' && phase === 'after');
+    if (absent ? parent !== null : parent === null) fail('ACTIVITY_E07_SUBJECT_PHASE_INVALID');
+    for (const key of ['revisionId', 'previousRevisionId', 'restoredRevisionId']) {
+        if (!p[key]) continue;
+        const revision = await load('revision', String(p[key]));
+        if (event.code === 'recurrence.created' && phase === 'before') {
+            if (revision) fail('ACTIVITY_E07_REVISION_ALREADY_EXISTS');
+            continue;
+        }
+        const optional = key === 'revisionId' && event.code === 'recurrence.config.updated' && phase === 'before';
+        if (!revision) {
+            if (optional) continue;
+            fail('ACTIVITY_E07_REVISION_UNAVAILABLE');
+        }
+        if (revision.kind !== 'revision' || revision.recurrenceId !== recurrenceId) fail('ACTIVITY_E07_REVISION_RELATION_INVALID');
+    }
+    const checkParent = async (id: string, optional = false) => {
+        const row = await mongoose.connection.db!.collection('transactions').findOne({ _id: new Types.ObjectId(id), accountId: new Types.ObjectId(accountId), parentTransactionId: null }, { session, projection: { _id: 1 } });
+        if (!row && !optional) fail('ACTIVITY_E07_PARENT_UNAVAILABLE');
+    };
+    if (event.subject.kind !== 'occurrence') return;
+    const occurrence = await load('occurrence', event.subject.id);
+    const optionalBefore = phase === 'before' && ['occurrence.generated', 'occurrence.skipped', 'occurrence.linked', 'occurrence.reassigned'].includes(event.code);
+    const optionalAfter = phase === 'after' && ['occurrence.unskipped', 'occurrence.unlinked'].includes(event.code) && !p.choice;
+    if (!occurrence && !optionalBefore && !optionalAfter) fail('ACTIVITY_E07_OCCURRENCE_UNAVAILABLE');
+    if (occurrence) {
+        if (occurrence.kind !== 'occurrence' || occurrence.recurrenceId !== recurrenceId || occurrence.occurrenceKey !== p.occurrenceKey) fail('ACTIVITY_E07_OCCURRENCE_RELATION_INVALID');
+        if (occurrence.transactionId) await checkParent(occurrence.transactionId);
+        if (phase === 'after' && ['occurrence.generated', 'occurrence.linked', 'occurrence.reassigned'].includes(event.code) && occurrence.transactionId !== p.transactionId) fail('ACTIVITY_E07_PARENT_RELATION_INVALID');
+        if (phase === 'before' && event.code === 'occurrence.unlinked' && occurrence.transactionId !== p.transactionId) fail('ACTIVITY_E07_PARENT_RELATION_INVALID');
+        if (phase === 'after' && (event.code === 'occurrence.skipped' || p.choice === 'release') && occurrence.transactionId !== null) fail('ACTIVITY_E07_RELEASE_STILL_LINKED');
+        if (phase === 'after' && event.code === 'occurrence.unlinked' && occurrence.transactionId === p.transactionId) fail('ACTIVITY_E07_OLD_PARENT_STILL_LINKED');
+    }
+    if (p.transactionId) await checkParent(String(p.transactionId), event.code === 'occurrence.generated' && phase === 'before');
+    if (event.code === 'occurrence.reassigned') {
+        const previousParent = await load('recurrence', String(p.previousRecurrenceId));
+        if (!previousParent) fail('ACTIVITY_E07_PREVIOUS_RECURRENCE_UNAVAILABLE');
+        const previous = await load('occurrence', String(p.previousOccurrenceId));
+        if (!previous && phase === 'before') fail('ACTIVITY_E07_PREVIOUS_OCCURRENCE_UNAVAILABLE');
+        if (previous) {
+            if (previous.kind !== 'occurrence' || previous.recurrenceId !== p.previousRecurrenceId || previous.occurrenceKey !== p.previousOccurrenceKey) fail('ACTIVITY_E07_PREVIOUS_RELATION_INVALID');
+            if (previous.transactionId) await checkParent(previous.transactionId);
+            if (phase === 'before' ? previous.transactionId !== p.transactionId : previous.transactionId === p.transactionId) fail('ACTIVITY_E07_REASSIGN_RELATION_INVALID');
+        }
+    }
+}"},{"sha":"6b00f0bd60c33f666cb30624c176fc43265ce78d","filename":"apps/api/src/services/recurrence-activity.ts","status":"added","additions":18,"deletions":0,"changes":18,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fapi%2Fsrc%2Fservices%2Frecurrence-activity.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,18 @@
+import type { ClientSession } from 'mongoose';
+import { isRecurrenceActivityCode, type RecurrenceActivityCode } from '@tobu/contracts/activity';
+import { activityCommand, commitActivity, writeActivityInSession, reconcileActivity, type ActivityAuthority, type ActivityIntent } from './activity-writer.js';
+import type { RecurrenceScopePort } from './recurrence-activity-scope.js';
+
+export type RecurrenceActivityIntent = Extract<ActivityIntent, { code: RecurrenceActivityCode }>;
+const checked = (intents: readonly RecurrenceActivityIntent[]) => {
+    if (!intents.length || intents.some((intent) => !isRecurrenceActivityCode(intent.code))) throw new Error('RECURRENCE_ACTIVITY_INTENTS_REQUIRED');
+    return intents;
+};
+type Command = ReturnType<typeof activityCommand>;
+/** Emit adapter only. The caller supplies the real domain guard/mutation and the same-session scope port. */
+export const commitRecurrenceActivity = (context: ActivityAuthority, command: Command, intents: readonly RecurrenceActivityIntent[], scope: RecurrenceScopePort, mutate: (session: ClientSession) => Promise<boolean>) =>
+    commitActivity(context, command, checked(intents), mutate, scope);
+export const writeRecurrenceActivityInSession = (session: ClientSession, context: ActivityAuthority, command: Command, intents: readonly RecurrenceActivityIntent[], scope: RecurrenceScopePort, mutate: (session: ClientSession) => Promise<boolean>) =>
+    writeActivityInSession(session, context, command, checked(intents), mutate, scope);
+export const reconcileRecurrenceActivity = (context: ActivityAuthority, command: Command, intents: readonly RecurrenceActivityIntent[], scope: RecurrenceScopePort, session?: ClientSession) =>
+    reconcileActivity(context, command, checked(intents), session, scope);"},{"sha":"11f706eca1738540b133a21c20d25e2162336b4a","filename":"apps/api/src/utils/renderEvent.ts","status":"modified","additions":4,"deletions":46,"changes":50,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Futils%2FrenderEvent.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fapi%2Fsrc%2Futils%2FrenderEvent.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fapi%2Fsrc%2Futils%2FrenderEvent.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -1,48 +1,6 @@
