+import {
+  ChangeDetectionStrategy,
+  Component,
+  computed,
+  DestroyRef,
+  ElementRef,
+  inject,
+  signal,
+  ViewChild,
+} from "@angular/core";
+import { ActivatedRoute, Router, RouterLink } from "@angular/router";
+import { FormsModule } from "@angular/forms";
+import { NgTemplateOutlet } from "@angular/common";
+import { takeUntilDestroyed } from "@angular/core/rxjs-interop";
+import { combineLatest, Subscription } from "rxjs";
+import { DateTime } from "luxon";
+import {
+  ACTIVITY_CODES,
+  ActivitySubjectKinds,
+  ActivityQuerySchema,
+  activityCodeNames,
+  ACTIVITY_TRIGGER_LABELS_DE,
+  renderActivityActor,
+  renderActivityText,
+  type ActivityItem,
+} from "@tobu/contracts/activity";
+import { ActivityDataService } from "./activity-data.service";
+import {
+  activityDisplayZone,
+  formatActivityInstant,
+  groupLoadedActivity,
+} from "./activity-presentation";
+
+@Component({
+  selector: "tbf-account-activity",
+  standalone: true,
+  changeDetection: ChangeDetectionStrategy.OnPush,
+  imports: [FormsModule, RouterLink, NgTemplateOutlet],
+  templateUrl: "./account-activity.html",
+  styleUrl: "./account-activity.scss",
+})
+export class AccountActivity {
+  private readonly route = inject(ActivatedRoute);
+  private readonly router = inject(Router);
+  private readonly data = inject(ActivityDataService);
+  private readonly destroy = inject(DestroyRef);
+  private request?: Subscription;
+  private generation = 0;
+  private filters: Record<string, string> = {};
+  private validFilters = false;
+  @ViewChild("resultsStatus") private status?: ElementRef<HTMLElement>;
+  protected readonly accountId = signal("");
+  protected readonly items = signal<ActivityItem[]>([]);
+  protected readonly groups = computed(() => groupLoadedActivity(this.items()));
+  protected readonly loading = signal(false);
+  protected readonly error = signal("");
+  protected readonly nextCursor = signal<string | null>(null);
+  protected readonly codes = ACTIVITY_CODES;
+  protected readonly kinds = ActivitySubjectKinds;
+  protected readonly codeNames = activityCodeNames;
+  protected readonly zone = activityDisplayZone();
+  protected form = {
+    code: "",
+    actorKind: "",
+    subjectKind: "",
+    subjectId: "",
+    from: "",
+    to: "",
+    limit: "20",
+  };
+  protected readonly kindLabels: Record<string, string> = {
+    account: "Konto",
+    member: "Mitglied",
+    transaction: "Buchung",
+    category: "Kategorie",
+    memberIncome: "Einkommen",
+    contributionRule: "Beitragsregel",
+    categoryBudget: "Budget",
+    carryOver: "Übertrag",
+    accountBalance: "Kontostand",
+    legacyRecurrence: "Wiederkehrende Buchung",
+    recurrence: "Buchungsvorlage",
+    occurrence: "Vorlagenvorkommen",
+  };
+  protected readonly actorText = renderActivityActor;
+  protected readonly eventText = renderActivityText;
+  protected readonly dateText = (date: string) =>
+    formatActivityInstant(date, this.zone);
+  protected readonly triggerText = (item: ActivityItem) =>
+    ACTIVITY_TRIGGER_LABELS_DE[item.trigger.kind];
+
+  constructor() {
+    combineLatest([this.route.parent!.paramMap, this.route.queryParamMap])
+      .pipe(takeUntilDestroyed())
+      .subscribe(([path, query]) => {
+        this.generation++;
+        this.validFilters = false;
+        this.filters = {};
+        this.request?.unsubscribe();
+        this.accountId.set(path.get("accountId") ?? "");
+        this.items.set([]);
+        this.nextCursor.set(null);
+        this.error.set("");
+        this.loading.set(false);
+        const raw: Record<string, string> = {};
+        for (const key of query.keys)
+          if (query.get(key)) raw[key] = query.get(key)!;
+        const parsed = ActivityQuerySchema.safeParse(raw);
+        if (!parsed.success || raw["cursor"]) {
+          this.error.set(
+            "Die Aktivitätsfilter sind ungültig. Bitte zurücksetzen.",
+          );
+          return;
+        }
+        this.filters = raw;
+        this.validFilters = true;
+        this.form = {
+          code: raw["code"] ?? "",
+          actorKind: raw["actorKind"] ?? "",
+          subjectKind: raw["subjectKind"] ?? "",
+          subjectId: raw["subjectId"] ?? "",
+          from: this.localInput(raw["from"]),
+          to: this.localInput(raw["to"]),
+          limit: raw["limit"] ?? "20",
+        };
+        this.load(false);
+      });
+    this.destroy.onDestroy(() => this.request?.unsubscribe());
+  }
+  private localInput(value?: string) {
+    return value
+      ? DateTime.fromISO(value, { zone: "utc" })
+          .setZone(this.zone)
+          .toFormat("yyyy-LL-dd'T'HH:mm:ss.SSS")
+      : "";
+  }
+  protected applyFilters() {
+    const query: Record<string, string> = {};
+    for (const [key, value] of Object.entries(this.form))
+      if (value.trim()) {
+        if (key === "from" || key === "to") {
+          const date = DateTime.fromISO(value, { zone: this.zone });
+          if (!date.isValid) {
+            this.error.set("Bitte einen gültigen Zeitpunkt eingeben.");
+            return;
+          }
+          query[key] = date.toUTC().toISO()!;
+        } else query[key] = value.trim();
+      }
+    if (!ActivityQuerySchema.safeParse(query).success) {
+      this.error.set(
+        "Bitte gültige Filter und einen Zeitraum mit Von vor Bis eingeben.",
+      );
+      return;
+    }
+    void this.router.navigate([], {
+      relativeTo: this.route,
+      queryParams: query,
+    });
+  }
+  protected resetFilters() {
+    void this.router.navigate([], { relativeTo: this.route, queryParams: {} });
+  }
+  protected loadMore() {
+    if (this.nextCursor() && !this.loading()) this.load(true);
+  }
+  protected retry() {
+    if (!this.loading())
+      this.load(this.items().length > 0 || this.nextCursor() !== null);
+  }
+  private load(append: boolean) {
+    if (!this.validFilters) return;
+    const generation = this.generation;
+    this.loading.set(true);
+    this.error.set("");
+    this.request = this.data
+      .get(
+        this.accountId(),
+        this.filters,
+        append ? (this.nextCursor() ?? undefined) : undefined,
+      )
+      .pipe(takeUntilDestroyed(this.destroy))
+      .subscribe({
+        next: (page) => {
+          if (generation !== this.generation) return;
+          const seen = new Set(
+            (append ? this.items() : []).map((item) => item.id),
+          );
+          const incoming = page.items.filter((item) => {
+            if (seen.has(item.id)) return false;
+            seen.add(item.id);
+            return true;
+          });
+          this.items.set([...(append ? this.items() : []), ...incoming]);
+          this.nextCursor.set(page.nextCursor);
+          this.loading.set(false);
+          if (append)
+            queueMicrotask(() =>
+              this.status?.nativeElement.focus({ preventScroll: true }),
+            );
+        },
+        error: (error: { status?: number }) => {
+          if (generation !== this.generation) return;
+          this.loading.set(false);
+          if (
+            error.status === 401 ||
+            error.status === 403 ||
+            error.status === 404
+          ) {
+            this.items.set([]);
+            this.nextCursor.set(null);
+          }
+          this.error.set(
+            error.status === 404
+              ? "Diese Kontoaktivitäten sind nicht verfügbar."
+              : error.status === 422
+                ? "Der Seitenbeleg oder die Filter sind nicht mehr gültig. Bitte zurücksetzen."
+                : "Aktivitäten konnten nicht geladen werden. Bitte erneut versuchen.",
+          );
+        },
+      });
+  }
+}"},{"sha":"101a591d7bfd42f0a50f517fcb996eb73b65963d","filename":"apps/web/src/app/accounts/activity/activity-data.service.ts","status":"added","additions":21,"deletions":0,"changes":21,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-data.service.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,21 @@
+import { inject, Injectable } from "@angular/core";
+import { HttpClient, HttpParams } from "@angular/common/http";
+import { map } from "rxjs";
+import { ActivityPageSchema } from "@tobu/contracts/activity";
+import { API_BASE_URL } from "@/core/api-base-url.token";
+
+@Injectable({ providedIn: "root" })
+export class ActivityDataService {
+  private readonly http = inject(HttpClient);
+  private readonly base = inject(API_BASE_URL);
+  get(accountId: string, filters: Record<string, string>, cursor?: string) {
+    let params = new HttpParams({ fromObject: { limit: "20", ...filters } });
+    if (cursor) params = params.set("cursor", cursor);
+    return this.http
+      .get<unknown>(
+        `${this.base}/api/accounts/${encodeURIComponent(accountId)}/activity`,
+        { params },
+      )
+      .pipe(map((body) => ActivityPageSchema.parse(body)));
+  }
+}"},{"sha":"59452e753424f51471b7b3b29fa89c96c69551dc","filename":"apps/web/src/app/accounts/activity/activity-presentation.spec.ts","status":"added","additions":137,"deletions":0,"changes":137,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.spec.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.spec.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.spec.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,137 @@
+import { TestBed } from "@angular/core/testing";
+import { provideHttpClient } from "@angular/common/http";
+import {
+  provideHttpClientTesting,
+  HttpTestingController,
+} from "@angular/common/http/testing";
+import {
+  ActivatedRoute,
+  convertToParamMap,
+  provideRouter,
+} from "@angular/router";
+import { BehaviorSubject } from "rxjs";
+import { ActivityItemSchema } from "@tobu/contracts/activity";
+import { API_BASE_URL } from "@/core/api-base-url.token";
+import { AccountActivity } from "./account-activity";
+import {
+  groupLoadedActivity,
+  formatActivityInstant,
+} from "./activity-presentation";
+
+const id = "a".repeat(24);
+const event = (n: number, grouped = true) =>
+  ActivityItemSchema.parse({
+    id: n.toString(16).padStart(24, "0"),
+    accountId: id,
+    occurredAt: "2026-11-08T12:00:00.000Z",
+    schemaVersion: 1,
+    code: "account.settings.updated",
+    actor: { kind: "user", memberId: null, displayName: null },
+    trigger: { kind: "user_action" },
+    subject: { kind: "account", id, deleted: false },
+    params: { changedFields: ["name"] },
+    ...(grouped
+      ? {
+          group: { key: "b".repeat(64), source: "batch", scope: "loaded_only" },
+        }
+      : {}),
+  });
+
+describe("E06 loaded activity and UTC instants", () => {
+  it("joins trusted groups over pages, deduplicates and never groups by timestamp", () => {
+    expect(
+      groupLoadedActivity([event(3), event(2), event(3), event(1)])[0].events
+        .length,
+    ).toBe(3);
+    expect(groupLoadedActivity([event(3, false), event(2, false)]).length).toBe(
+      2,
+    );
+    expect(groupLoadedActivity([event(3)])[0].grouped).toBeTrue();
+  });
+  it("displays the same real instant in explicit zones including midnight", () => {
+    expect(formatActivityInstant("2026-11-08T00:00:00.000Z", "UTC")).toContain(
+      "08.11.2026 00:00:00",
+    );
+    expect(
+      formatActivityInstant("2026-11-08T00:00:00.000Z", "America/Los_Angeles"),
+    ).toContain("07.11.2026 16:00:00");
+  });
+});
+
+describe("E06 route lifetime and validated page consumption", () => {
+  let http: HttpTestingController;
+  let path: BehaviorSubject<ReturnType<typeof convertToParamMap>>;
+  let query: BehaviorSubject<ReturnType<typeof convertToParamMap>>;
+  beforeEach(() => {
+    path = new BehaviorSubject(convertToParamMap({ accountId: id }));
+    query = new BehaviorSubject(convertToParamMap({}));
+    TestBed.configureTestingModule({
+      imports: [AccountActivity],
+      providers: [
+        provideHttpClient(),
+        provideHttpClientTesting(),
+        provideRouter([]),
+        { provide: API_BASE_URL, useValue: "" },
+        {
+          provide: ActivatedRoute,
+          useValue: { parent: { paramMap: path }, queryParamMap: query },
+        },
+      ],
+    });
+    http = TestBed.inject(HttpTestingController);
+  });
+  afterEach(() => http.verify({ ignoreCancelled: true }));
+  it("cancels previous-account responses and fails closed on invalid URL even after retry", () => {
+    const fixture = TestBed.createComponent(AccountActivity);
+    const old = http.expectOne(`/api/accounts/${id}/activity?limit=20`);
+    const other = "c".repeat(24);
+    path.next(convertToParamMap({ accountId: other }));
+    expect(old.cancelled).toBeTrue();
+    const current = http.expectOne(`/api/accounts/${other}/activity?limit=20`);
+    current.flush({ items: [], nextCursor: null });
+    query.next(convertToParamMap({ limit: "101" }));
+    fixture.detectChanges();
+    const button = Array.from(
+      fixture.nativeElement.querySelectorAll(
+        "button",
+      ) as NodeListOf<HTMLButtonElement>,
+    ).find((b) => b.textContent?.includes("Erneut versuchen"))!;
+    button.click();
+    http.expectNone((req) => req.url.includes("/activity"));
+    fixture.destroy();
+  });
+  it("retains loaded groups after a page fault, retries same cursor and clears on access loss", () => {
+    const fixture = TestBed.createComponent(AccountActivity);
+    http
+      .expectOne(`/api/accounts/${id}/activity?limit=20`)
+      .flush({ items: [event(2)], nextCursor: "opaque" });
+    fixture.detectChanges();
+    const more = () =>
+      (
+        fixture.nativeElement.querySelector(".load-more") as HTMLButtonElement
+      ).click();
+    more();
+    http
+      .expectOne(`/api/accounts/${id}/activity?limit=20&cursor=opaque`)
+      .flush("unavailable", { status: 503, statusText: "Unavailable" });
+    fixture.detectChanges();
+    expect(fixture.nativeElement.textContent).toContain("1 Ereignisse geladen");
+    more();
+    http
+      .expectOne(`/api/accounts/${id}/activity?limit=20&cursor=opaque`)
+      .flush({ items: [event(1)], nextCursor: null });
+    fixture.detectChanges();
+    expect(fixture.nativeElement.textContent).toContain(
+      "2 geladene Ereignisse einer Aktion",
+    );
+    query.next(convertToParamMap({ actorKind: "system" }));
+    http
+      .expectOne(`/api/accounts/${id}/activity?limit=20&actorKind=system`)
+      .flush("not found", { status: 404, statusText: "Not Found" });
+    fixture.detectChanges();
+    expect(
+      fixture.nativeElement.querySelectorAll("[data-event-id]").length,
+    ).toBe(0);
+    fixture.destroy();
+  });
+});"},{"sha":"3e30cd9e1f727b1e54a5913c42bb8dc44d24d8e6","filename":"apps/web/src/app/accounts/activity/activity-presentation.ts","status":"added","additions":40,"deletions":0,"changes":40,"blob_url":"https://github.com/ChroniX6x/tobu-finance/blob/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.ts","raw_url":"https://github.com/ChroniX6x/tobu-finance/raw/43c3883ab1fde44bedae4012f69706af8b29a25e/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.ts","contents_url":"https://api.github.com/repos/ChroniX6x/tobu-finance/contents/apps%2Fweb%2Fsrc%2Fapp%2Faccounts%2Factivity%2Factivity-presentation.ts?ref=43c3883ab1fde44bedae4012f69706af8b29a25e","patch":"@@ -0,0 +1,40 @@
+import { DateTime } from "luxon";
+import type { ActivityItem } from "@tobu/contracts/activity";
+
+export interface ActivityGroup {
+  key: string;
+  events: ActivityItem[];
+  grouped: boolean;
+}
+/** Rebuild from all loaded pages, never invent an expected count or a successful batch result. */
+export function groupLoadedActivity(
+  items: readonly ActivityItem[],
+): ActivityGroup[] {
+  const seen = new Set<string>();
+  const groups = new Map<string, ActivityGroup>();
+  for (const item of items) {
+    if (seen.has(item.id)) continue;
+    seen.add(item.id);
+    const key = item.group ? "group:" + item.group.key : "event:" + item.id;
+    const group = groups.get(key) ?? {
+      key,
+      events: [],
+      grouped: item.group?.source === "batch",
+    };
+    group.events.push(item);
+    group.grouped ||= group.events.length > 1;
+    groups.set(key, group);
+  }
+  return [...groups.values()];
+}
